{-# LANGUAGE OverloadedStrings #-}

module Main where

import Gauge
import Raehik.HexByteString
import Data.Text ( Text )

hbs0Short :: Text
hbs0Short = "00FF"

hbs1Mid :: Text
hbs1Mid = "00  FF00FF00FF00FF00FF00FF00FF00FF00FF00FF"

hbs2Long :: Text
hbs2Long = "00  "

hbs3ELong :: Text
hbs3ELong = "00  "

main :: IO ()
main = defaultMain
  [ bgroup "hexbs"
    [ bench "trim     short"  $ nfAppIO textToByteStringTrimIO    hbs0Short
    , bench "upto     short"  $ nfAppIO textToByteStringUptoIO    hbs0Short
    , bench "trim CPS short"  $ nfAppIO textToByteStringTrimCPSIO hbs0Short
    , bench "upto CPS short"  $ nfAppIO textToByteStringUptoCPSIO hbs0Short
    , bench "bytezap  short"  $ nf      textToByteString          hbs0Short
    , bench "trim       mid"  $ nfAppIO textToByteStringTrimIO    hbs1Mid
    , bench "upto       mid"  $ nfAppIO textToByteStringUptoIO    hbs1Mid
    , bench "trim CPS   mid"  $ nfAppIO textToByteStringTrimCPSIO hbs1Mid
    , bench "upto CPS   mid"  $ nfAppIO textToByteStringUptoCPSIO hbs1Mid
    , bench "bytezap    mid"  $ nf      textToByteString          hbs1Mid
    , bench "trim      long"  $ nfAppIO textToByteStringTrimIO    hbs2Long
    , bench "upto      long"  $ nfAppIO textToByteStringUptoIO    hbs2Long
    , bench "trim CPS  long"  $ nfAppIO textToByteStringTrimCPSIO hbs2Long
    , bench "upto CPS  long"  $ nfAppIO textToByteStringUptoCPSIO hbs2Long
    , bench "bytezap   long"  $ nf      textToByteString          hbs2Long
    , bench "trim     elong"  $ nfAppIO textToByteStringTrimIO    hbs3ELong
    , bench "upto     elong"  $ nfAppIO textToByteStringUptoIO    hbs3ELong
    , bench "trim CPS elong"  $ nfAppIO textToByteStringTrimCPSIO hbs3ELong
    , bench "upto CPS elong"  $ nfAppIO textToByteStringUptoCPSIO hbs3ELong
    , bench "bytezap  elong"  $ nf      textToByteString          hbs3ELong
    ]
  ]
